def migrate_actions_to_steps(apps, schema_editor):
    """
    Turn every existing linear AutomationAction list into a step chain.

    AutomationAction stays readable for a release, so this is not a move - it is a
    copy. An automation that already has steps is left alone: re-running the
    migration (or a half-finished manual migration) must not duplicate its graph.
    """
    Automation = apps.get_model('automations', 'Automation')
    AutomationAction = apps.get_model('automations', 'AutomationAction')
    AutomationStep = apps.get_model('automations', 'AutomationStep')
    AutomationEdge = apps.get_model('automations', 'AutomationEdge')

    automations = Automation.objects.filter(
        actions__isnull=False,
        steps__isnull=True,
    ).distinct()

    for automation in automations:
        actions = AutomationAction.objects.filter(
            automation=automation,
        ).order_by('order', 'created_at')

        steps = []
        for idx, action in enumerate(actions, start=1):
            steps.append(AutomationStep.objects.create(
                automation=automation,
                step_type='action',
                key=str(idx),
                action_type=action.action_type,
                config=action.config,
                channel_id=action.channel_id,
                template_id=action.template_id,
                on_failure=action.on_failure,
            ))

        if not steps:
            continue

        # None -> first step is the entry edge; the rest is a linear chain, which is
        # exactly what an ordered action list was.
        AutomationEdge.objects.create(
            automation=automation,
            from_step=None,
            to_step=steps[0],
            branch_key='',
            order=0,
        )
        for i in range(1, len(steps)):
            AutomationEdge.objects.create(
                automation=automation,
                from_step=steps[i - 1],
                to_step=steps[i],
                branch_key='',
                order=i,
            )


